import{_ as r,o as s,c as t,a2 as a}from"./chunks/framework.ChIlRNAd.js";const h=JSON.parse('{"title":"Archives","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/archives.md","filePath":"fr/guide/archives.md"}'),i={name:"fr/guide/archives.md"};function n(o,e,l,u,g,c){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="archives" tabindex="-1">Archives <a class="header-anchor" href="#archives" aria-label="Permalink to &quot;Archives&quot;">​</a></h1><p>La page <strong>Archives</strong> (<code>/archives</code>) donne accès à la copie locale de vos mails, sauvegardée sur le NAS au format EML. Elle reste consultable même si les mails ont été supprimés de Gmail, et même si le compte Gmail a été déconnecté.</p><p>Quatre onglets : <strong>Mails</strong>, <strong>Corbeille</strong>, <strong>Rétention</strong>, <strong>Partages</strong>.</p><hr><h2 id="en-tete-et-sauvegarde" tabindex="-1">En-tête et sauvegarde <a class="header-anchor" href="#en-tete-et-sauvegarde" aria-label="Permalink to &quot;En-tête et sauvegarde&quot;">​</a></h2><ul><li>État : « Dernière sauvegarde il y a … · N mails » (ou « Aucune sauvegarde pour l&#39;instant »).</li><li><strong>Sauvegarder sur le NAS maintenant</strong> : sauvegarde les mails du compte pas encore archivés ; la progression s&#39;affiche sous l&#39;en-tête et dans <a href="./activity.html">Activité</a>.</li><li><strong>Exporter (.mbox)</strong> : télécharge les archives du compte au format mbox (lisible par Thunderbird ou Apple Mail). Si une recherche ou un filtre est actif, seuls les résultats chargés sont exportés.</li></ul><p>D&#39;autres façons d&#39;alimenter les archives : <strong>Sauvegarder sur le NAS</strong> dans <a href="./mails.html">Mails</a>, la <strong>Sauvegarde automatique</strong> d&#39;un compte dans <a href="./settings.html#comptes-gmail">Paramètres › Comptes Gmail</a>, les règles « Sauvegarder sur le NAS puis supprimer » et l&#39;import mbox / IMAP de <a href="./settings.html#donnees">Paramètres › Données</a>.</p><hr><h2 id="onglet-mails-rechercher" tabindex="-1">Onglet Mails : rechercher <a class="header-anchor" href="#onglet-mails-rechercher" aria-label="Permalink to &quot;Onglet Mails : rechercher&quot;">​</a></h2><ul><li><strong>Arbre des libellés</strong> (à gauche sur ordinateur) : <strong>Tous les mails</strong> puis les libellés qui contiennent des mails archivés, avec leur nombre.</li><li><strong>Recherche plein texte</strong> : « Rechercher dans les archives (objet, expéditeur, contenu…) ». Les termes trouvés sont surlignés dans l&#39;extrait.</li><li><strong>Filtres</strong> : <strong>Expéditeur</strong>, période (<strong>Du</strong> / <strong>Au</strong>), <strong>Avec pièce jointe</strong>. Sur mobile, ils sont regroupés dans le panneau <strong>Filtres (N)</strong> avec le <strong>Libellé</strong>, puis <strong>Afficher les résultats</strong>.</li></ul><p>Les résultats (« N résultats ») affichent <strong>Objet</strong>, <strong>Extrait</strong>, <strong>Date</strong>, <strong>Expéditeur</strong>, <strong>Taille</strong>. <strong>Effacer la recherche et les filtres</strong> revient à la liste complète.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><ul><li>Menu <code>⋯</code> d&#39;une ligne : <strong>Ouvrir</strong>, <strong>Partager</strong>, <strong>Supprimer</strong>.</li><li>Sélection de plusieurs lignes : <strong>Exporter .mbox</strong>, <strong>Supprimer</strong>.</li></ul><p><strong>Supprimer</strong> envoie les archives dans la corbeille des archives, avec un toast « Suppression de N archives dans 10 s » et <strong>Annuler</strong>.</p><h3 id="lecteur-d-archive" tabindex="-1">Lecteur d&#39;archive <a class="header-anchor" href="#lecteur-d-archive" aria-label="Permalink to &quot;Lecteur d&#39;archive&quot;">​</a></h3><p><strong>Ouvrir</strong> affiche le mail archivé : en-têtes, corps (images distantes bloquées, comme dans <a href="./mails.html#lire-un-mail">Mails</a>), pièces jointes téléchargeables et <strong>Conversation</strong>. Actions : <strong>Partager</strong>, <strong>Supprimer</strong>.</p><p>Un mail archivé chiffré affiche « Ce mail est chiffré : son contenu n&#39;est pas lisible ici. » Le chiffrement des archives ne se règle pas depuis l&#39;interface.</p><hr><h2 id="partager-un-mail" tabindex="-1">Partager un mail <a class="header-anchor" href="#partager-un-mail" aria-label="Permalink to &quot;Partager un mail&quot;">​</a></h2><p><strong>Partager</strong> ouvre « Partager ce mail » : un lien temporaire, lisible sans compte Nid.</p><ol><li>Choisissez la <strong>Durée de validité</strong> : 1 heure, 24 heures, 3 jours, 7 jours ou 30 jours.</li><li><strong>Créer le lien</strong>, puis copiez-le.</li></ol><p>La fenêtre liste aussi les liens actifs de ce mail (« Expire le … ») avec les boutons copier et révoquer.</p><p>La personne qui ouvre le lien voit le mail (« Mail partagé via lien temporaire »), images distantes bloquées. Un lien expiré, révoqué ou ayant atteint sa limite d&#39;accès affiche « Lien introuvable ».</p><h3 id="onglet-partages" tabindex="-1">Onglet Partages <a class="header-anchor" href="#onglet-partages" aria-label="Permalink to &quot;Onglet Partages&quot;">​</a></h3><p>Tous vos liens actifs : <strong>Objet</strong>, <strong>Expéditeur</strong>, <strong>Expire le</strong>, <strong>Accès</strong> (ouvertures / limite), copier, révoquer. Le nombre de liens actifs est aussi rappelé dans <a href="./settings.html#securite">Paramètres › Sécurité</a>.</p><hr><h2 id="onglet-corbeille" tabindex="-1">Onglet Corbeille <a class="header-anchor" href="#onglet-corbeille" aria-label="Permalink to &quot;Onglet Corbeille&quot;">​</a></h2><p>Les archives supprimées y restent avant d&#39;être effacées du NAS.</p><ul><li>« N mails dans la corbeille », avec la date <strong>Supprimé le</strong>.</li><li><strong>Restaurer</strong> un mail, ou sélectionnez-en plusieurs puis <strong>Restaurer</strong>.</li><li><strong>Vider la corbeille</strong> : après confirmation, supprime définitivement les mails et leurs pièces jointes du NAS. Irréversible.</li><li>Purge automatique : « Les mails de la corbeille sont supprimés définitivement après N jours » (ou « Purge automatique de la corbeille désactivée »). Les administrateurs règlent ici <strong>Purge automatique</strong> et <strong>Durée avant purge (jours)</strong> pour toute l&#39;instance (voir aussi <a href="./admin.html#systeme">Admin › Système</a>).</li></ul><hr><h2 id="onglet-retention" tabindex="-1">Onglet Rétention <a class="header-anchor" href="#onglet-retention" aria-label="Permalink to &quot;Onglet Rétention&quot;">​</a></h2><p>« Supprime les archives plus anciennes qu&#39;une durée, pour un libellé ou toutes. »</p><ul><li><strong>Nouvelle politique</strong> : <strong>Nom</strong>, <strong>Libellé</strong> (ou <strong>Tous les libellés</strong>), <strong>Supprimer après (jours)</strong>.</li><li>La liste affiche <strong>Nom</strong>, <strong>Libellé</strong>, <strong>Âge</strong> (« Plus de N jours ») et <strong>Dernière exécution</strong> (avec le nombre d&#39;archives supprimées).</li><li><strong>Exécuter maintenant</strong> applique toutes les politiques.</li><li>Menu d&#39;une politique : modifier, supprimer (après confirmation ; les archives déjà supprimées ne reviennent pas).</li></ul><p>Sans politique, les archives sont conservées sans limite de durée.</p>',34)])])}const d=r(i,[["render",n]]);export{h as __pageData,d as default};
